def solve(items: list[str]) -> list[str]:
    def sort_key(value: str) -> tuple:
        runs = []
        digit_lengths = []
        i = 0

        while i < len(value):
            is_digit = "0" <= value[i] <= "9"
            j = i + 1
            while j < len(value) and ("0" <= value[j] <= "9") == is_digit:
                j += 1

            run = value[i:j]
            if is_digit:
                canonical = run.lstrip("0") or "0"
                runs.append((0, len(canonical), canonical))
                digit_lengths.append(len(run))
            else:
                runs.append((1, run.lower()))
            i = j

        return tuple(runs), tuple(digit_lengths), value

    return sorted(items, key=sort_key)

def solve(buildings: list[tuple[int, int, int]]) -> list[tuple[int, int]]:
    from heapq import heappop, heappush

    starts: dict[int, list[tuple[int, int]]] = {}
    coordinates = set()

    for left, right, height in buildings:
        if height > 0:
            starts.setdefault(left, []).append((height, right))
            coordinates.add(left)
            coordinates.add(right)

    active: list[tuple[int, int]] = []
    points: list[tuple[int, int]] = []
    current_height = 0

    for x in sorted(coordinates):
        for height, right in starts.get(x, ()):
            heappush(active, (-height, right))

        while active and active[0][1] <= x:
            heappop(active)

        height = -active[0][0] if active else 0
        if height != current_height:
            points.append((x, height))
            current_height = height

    return points

def solve(n: int, places: int) -> str:
    import math

    scale = 10 ** places
    value = math.isqrt(n * scale * scale)
    integer, fraction = divmod(value, scale)
    if places == 0:
        return str(integer)
    return f"{integer}.{fraction:0{places}d}"

def solve(text: str) -> int | None:
    if not text:
        return None

    base = 10
    body = text
    prefixed = False

    if len(text) >= 2 and text[0] == "0":
        prefix = text[1]
        if prefix in "bB":
            base, body, prefixed = 2, text[2:], True
        elif prefix in "oO":
            base, body, prefixed = 8, text[2:], True
        elif prefix in "xX":
            base, body, prefixed = 16, text[2:], True

    def digit_value(char: str) -> int:
        code = ord(char)
        if 48 <= code <= 57:
            return code - 48
        if 65 <= code <= 70:
            return code - 65 + 10
        if 97 <= code <= 102:
            return code - 97 + 10
        return -1

    if prefixed and body.startswith("_"):
        body = body[1:]

    if not body:
        return None

    value = 0
    digit_count = 0
    first_digit = -1
    previous_was_digit = False

    for index, char in enumerate(body):
        if char == "_":
            if (
                not previous_was_digit
                or index + 1 == len(body)
                or not (0 <= digit_value(body[index + 1]) < base)
            ):
                return None
            previous_was_digit = False
            continue

        digit = digit_value(char)
        if not 0 <= digit < base:
            return None

        if digit_count == 0:
            first_digit = digit
        digit_count += 1
        value = value * base + digit
        previous_was_digit = True

    if digit_count == 0:
        return None
    if not prefixed and first_digit == 0 and value != 0:
        return None

    return value

def solve(lo: int, hi: int, digit: int) -> int:
    def count_up_to(n: int) -> int:
        if n < 0:
            return 0

        total = 1 if digit == 0 else 0
        factor = 1

        while factor <= n:
            lower = n % factor
            current = (n // factor) % 10
            higher = n // (factor * 10)

            if digit == 0:
                if higher:
                    total += (higher - 1) * factor
                    total += lower + 1 if current == 0 else factor
            else:
                total += higher * factor
                if current > digit:
                    total += factor
                elif current == digit:
                    total += lower + 1

            factor *= 10

        return total

    return count_up_to(hi) - count_up_to(lo - 1)

def solve(values: list[int], k: int) -> list[int]:
    n = len(values)

    def feasible(limit: int) -> bool:
        parts = 1
        total = 0
        for value in values:
            if total + value > limit:
                parts += 1
                total = value
            else:
                total += value
        return parts <= k

    low = max(values)
    high = sum(values)
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    limit = low

    furthest = [0] * n
    end = 0
    window = 0
    for start in range(n):
        while end < n and window + values[end] <= limit:
            window += values[end]
            end += 1
        furthest[start] = end
        window -= values[start]

    min_parts = [0] * (n + 1)
    for start in range(n - 1, -1, -1):
        min_parts[start] = 1 + min_parts[furthest[start]]

    lengths = []
    start = 0
    remaining = k
    while remaining > 1:
        end = min(furthest[start], n - remaining + 1)
        if min_parts[end] > remaining - 1:
            raise ValueError("No valid split")
        lengths.append(end - start)
        start = end
        remaining -= 1

    lengths.append(n - start)
    return lengths

def solve(records: list[dict], spec: str) -> list[int]:
    from functools import cmp_to_key

    fields = [(part[1:], True) if part.startswith("-") else (part, False)
              for part in spec.split(",")]

    def compare(i: int, j: int) -> int:
        left_record, right_record = records[i], records[j]

        for field, descending in fields:
            left = left_record.get(field)
            right = right_record.get(field)
            left_empty = left is None
            right_empty = right is None

            if left_empty or right_empty:
                if left_empty != right_empty:
                    return 1 if left_empty else -1
                continue

            if isinstance(left, int) and isinstance(right, str):
                result = -1
            elif isinstance(left, str) and isinstance(right, int):
                result = 1
            elif isinstance(left, int) and isinstance(right, int):
                result = (left > right) - (left < right)
            else:
                left_key = (left.lower(), left)
                right_key = (right.lower(), right)
                result = (left_key > right_key) - (left_key < right_key)

            if result:
                return -result if descending else result

        return 0

    return sorted(range(len(records)), key=cmp_to_key(compare))

def solve(text: str, need: str) -> str:
    if not need:
        return ""

    required = {}
    for char in need:
        required[char] = required.get(char, 0) + 1

    window = {}
    formed = 0
    left = 0
    best_start = 0
    best_length = len(text) + 1

    for right, char in enumerate(text):
        if char in required:
            window[char] = window.get(char, 0) + 1
            if window[char] == required[char]:
                formed += 1

        while formed == len(required):
            length = right - left + 1
            if length < best_length:
                best_start = left
                best_length = length

            left_char = text[left]
            if left_char in required:
                if window[left_char] == required[left_char]:
                    formed -= 1
                window[left_char] -= 1
            left += 1

    return "" if best_length == len(text) + 1 else text[best_start:best_start + best_length]

def solve(text: str) -> dict[str, dict[str, str]] | None:
    sections: dict[str, dict[str, str]] = {}
    current = ""

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        line = line.strip(" \t")

        if not line or line[0] in ";#":
            continue

        if line.startswith("[") and line.endswith("]"):
            name = line[1:-1].strip(" \t").lower()
            if not name:
                return None
            current = name
            sections.setdefault(current, {})
        elif "=" in line:
            key, value = line.split("=", 1)
            key = key.strip(" \t").lower()
            if not key:
                return None
            value = value.strip(" \t")
            if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            sections.setdefault(current, {})[key] = value
        else:
            return None

    return sections

from fractions import Fraction


def solve(a: list[list[int]], b: list[int]) -> list[tuple[int, int]] | str:
    m = len(a)
    n = len(a[0])
    matrix = [
        [Fraction(value) for value in a[i]] + [Fraction(b[i])]
        for i in range(m)
    ]

    pivot_row = 0
    pivot_columns = []

    for column in range(n):
        pivot = next(
            (row for row in range(pivot_row, m) if matrix[row][column]),
            None,
        )
        if pivot is None:
            continue

        matrix[pivot_row], matrix[pivot] = matrix[pivot], matrix[pivot_row]
        pivot_value = matrix[pivot_row][column]
        matrix[pivot_row] = [value / pivot_value for value in matrix[pivot_row]]

        for row in range(m):
            if row != pivot_row and matrix[row][column]:
                factor = matrix[row][column]
                matrix[row] = [
                    value - factor * pivot
                    for value, pivot in zip(matrix[row], matrix[pivot_row])
                ]

        pivot_columns.append(column)
        pivot_row += 1
        if pivot_row == m:
            break

    for row in matrix:
        if all(value == 0 for value in row[:n]) and row[n] != 0:
            return "none"

    if len(pivot_columns) < n:
        return "many"

    solution = [Fraction(0) for _ in range(n)]
    for row, column in enumerate(pivot_columns):
        solution[column] = matrix[row][n]

    return [(value.numerator, value.denominator) for value in solution]

def solve(heights: list[list[int]]) -> int:
    import heapq

    if not heights or not heights[0]:
        return 0

    rows, cols = len(heights), len(heights[0])
    visited = [[False] * cols for _ in range(rows)]
    frontier = []

    for r in range(rows):
        for c in (0, cols - 1):
            if not visited[r][c]:
                visited[r][c] = True
                heapq.heappush(frontier, (heights[r][c], r, c))

    for c in range(cols):
        for r in (0, rows - 1):
            if not visited[r][c]:
                visited[r][c] = True
                heapq.heappush(frontier, (heights[r][c], r, c))

    trapped = 0
    while frontier:
        level, r, c = heapq.heappop(frontier)
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                visited[nr][nc] = True
                height = heights[nr][nc]
                if height < level:
                    trapped += level - height
                heapq.heappush(frontier, (max(level, height), nr, nc))

    return trapped

def solve(query: str) -> dict[str, list[str]]:
    if query.startswith("?"):
        query = query[1:]

    result: dict[str, list[str]] = {}

    def decode(text: str) -> str:
        data = bytearray()
        i = 0

        while i < len(text):
            char = text[i]
            if char == "+":
                data.append(0x20)
                i += 1
            elif char == "%" and i + 2 < len(text):
                try:
                    data.append(int(text[i + 1:i + 3], 16))
                    i += 3
                except ValueError:
                    data.extend(char.encode("utf-8"))
                    i += 1
            else:
                data.extend(char.encode("utf-8"))
                i += 1

        return data.decode("utf-8", "replace")

    for piece in query.split("&"):
        if not piece:
            continue

        if "=" in piece:
            name, value = piece.split("=", 1)
        else:
            name, value = piece, ""

        decoded_name = decode(name)
        result.setdefault(decoded_name, []).append(decode(value))

    return result

def solve(program: list[str]) -> list[int] | None:
    def wrap(value: int) -> int:
        value &= 0xFFFFFFFF
        return value - 0x100000000 if value >= 0x80000000 else value

    stack: list[int] = []

    for instruction in program:
        if instruction.startswith("push "):
            operand = instruction[5:]
            negative = operand.startswith("-")
            digits = operand[1:] if negative else operand
            if not digits or any(ch < "0" or ch > "9" for ch in digits):
                return None

            value = 0
            for ch in digits:
                value = (value * 10 + ord(ch) - ord("0")) & 0xFFFFFFFF
            stack.append(wrap(-value if negative else value))
        elif instruction == "pop":
            if len(stack) < 1:
                return None
            stack.pop()
        elif instruction == "dup":
            if len(stack) < 1:
                return None
            stack.append(stack[-1])
        elif instruction == "swap":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == "neg":
            if len(stack) < 1:
                return None
            stack[-1] = wrap(-stack[-1])
        elif instruction in ("add", "sub", "mul", "div", "mod"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()

            if instruction == "add":
                result = a + b
            elif instruction == "sub":
                result = a - b
            elif instruction == "mul":
                result = a * b
            else:
                if b == 0:
                    return None
                quotient = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    quotient = -quotient
                result = quotient if instruction == "div" else a - b * quotient

            stack.append(wrap(result))
        else:
            return None

    return stack
